--liquibase formatted sql

--changeset minipolya:005-create-booking-series
--comment: Recurring booking templates (day_of_week: 0=Monday .. 6=Sunday); bookings generated by BookingSeriesJob in step 20
CREATE TABLE booking_series (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id        BIGINT NOT NULL REFERENCES users (id),
    stadium_id     BIGINT NOT NULL REFERENCES stadiums (id) ON DELETE CASCADE,
    day_of_week    INTEGER NOT NULL CHECK (day_of_week BETWEEN 0 AND 6),
    start_time     TIME NOT NULL,
    duration_hours INTEGER NOT NULL CHECK (duration_hours IN (1, 2)),
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_booking_series_stadium_day ON booking_series (stadium_id, day_of_week);
